// migrate.js
// Reads SQL migration files from ./migrations/ directory and logs each filename
// that would be applied, in order.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Directory ${MIGRATIONS_DIR} does not exist.`);
    process.exit(1);
  }

  const files = fs.readdirSync(MIGRATIONS_DIR);
  // Filter only .sql files (case-insensitive)
  const sqlFiles = files.filter(file => file.toLowerCase().endsWith('.sql'));
  // Sort alphabetically (or by numeric prefix if present)
  sqlFiles.sort();
  return sqlFiles;
}

function main() {
  const migrations = getMigrationFiles();
  if (migrations.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log(`Found ${migrations.length} migration(s) in ${MIGRATIONS_DIR}\n`);
  migrations.forEach((file, index) => {
    console.log(`Applying migration ${index + 1}/${migrations.length}: ${file}`);
    // Here you would actually apply the migration, e.g., read the file and run the SQL.
    // For this exercise, we just log the filename.
  });
}

if (require.main === module) {
  main();
}

