 * from a .env.test file, logging a message that it "connected".
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from a .env.test file. Returns an object with
 * key/value pairs. For this script we only care about DATABASE_URL.
 */
function loadEnv() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`.${path.basename(ENV_FILE)} file not found. Skipping env load.`);
    return {};
  }

  const content = fs.readFileSync(ENV_FILE, { encoding: 'utf8' });
  const env = {};
  content.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;
    const [key, ...rest] = trimmed.split('=');
    const value = rest.join('=');
    env[key] = value.replace(/^\s*"|\s*"$/g, ''); // simple strip of surrounding quotes
  });
  return env;
}

/**
 * Return a sorted list of .sql files in the migrations directory.
 */
function getMigrationFiles() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Directory ${MIGRATIONS_DIR} does not exist.`);
    process.exit(1);
  }

  const files = fs.readdirSync(MIGRATIONS_DIR);
  const sqlFiles = files
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();
  return sqlFiles;
}

function main() {
  // Resolve env and attempt "connection"
  const env = loadEnv();
  if (env.DATABASE_URL) {
    console.log(`Connected to database: ${env.DATABASE_URL}`);
  } else {
    console.warn('DATABASE_URL not found in .env.test. Skipping connection log.');
  }

  const migrations = getMigrationFiles();
  if (migrations.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log(`Found ${migrations.length} migration(s) in ${MIGRATIONS_DIR}\n`);
  migrations.forEach((file, idx) => {
    console.log(`Applying migration ${idx + 1}/${migrations.length}: ${file}`);
    // Here you would actually apply the migration
  });
}

if (require.main === module) {
  main();
}

