#!/usr/bin/env node

/**
 * Simple migration logger
 *
 * This script reads all .sql files from the ./migrations/ directory,
 * sorts them alphabetically, and logs each filename that would be applied.
 * It does NOT execute the SQL statements – it only reports the order.
 *
 * Usage:
 *   node migrate.js
 */

const fs = require('fs').promises;
const path = require('path');

// Path to the migrations directory (relative to this script)
const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

async function run() {
  try {
    // Check the migrations directory existence
    await fs.access(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  let files;
  try {
    // Read all entries in the directory
    files = await fs.readdir(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Failed to read migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter((file) => file.endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations that would be applied:');
  for (const file of sqlFiles) {
    console.log(`  - ${file}`);
  }
}

run();

