  // Ensure migrations folder exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.warn(`Directory ${MIGRATIONS_DIR} does not exist. Nothing to migrate.`);
    process.exit(0);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files
  const sqlFiles = files
    .filter((file) => path.extname(file).toLowerCase() === '.sql')
    .sort(); // alphabetic order – deterministic

  if (sqlFiles.length === 0) {
    console.log('No migration SQL files found in', MIGRATIONS_DIR);
    process.exit(0);
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach((file) => {
    console.log('  -', file);
  });
} catch (err) {
  console.error('Error while preparing migrations:', err);
  process.exit(1);
}

