#!/usr/bin/env node

/*
 * migrate.js
 * -----------------
 * This simple migration script demonstrates how to read a list of SQL files
 * stored inside a `./migrations/` directory and log, in order, each file that
 * would be applied.
 *
 * It does **not** execute the SQL statements – it only pretends to apply the
 * migrations by printing the file name to the console.
 *
 * Usage:
 *   node migrate.js
 */

const fs = require('fs/promises');
const path = require('path');

async function run() {
  try {
    const migrationsDir = path.resolve(__dirname, 'migrations');
    const entries = await fs.readdir(migrationsDir, { withFileTypes: true });

    // Filter for regular files ending with .sql
    const sqlFiles = entries
      .filter((entry) => entry.isFile() && entry.name.endsWith('.sql'))
      .map((entry) => entry.name)
      .sort(); // sort alphabetically (or could use another ordering)

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in', migrationsDir);
      return;
    }

    console.log('Found', sqlFiles.length, 'migration(\u200b)s:');
    for (const file of sqlFiles) {
      console.log('->', file);
    }
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
}

run();

