#!/usr/bin/env node

/**
 * Simple migration logger
 *
 * This script scans the `./migrations/` directory for SQL files
 * and prints each migration file name in order.
 * It does NOT execute the migrations; it only reports what would be applied.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

/**
 * Return a sorted list of .sql filenames in the migrations directory.
 *
 * @param {string} dir - Directory to search
 * @returns {string[]} Sorted array of filenames
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.warn(`Migrations directory ${dir} does not exist.`);
    return [];
  }

  return fs
    .readdirSync(dir)
    .filter(file => file.endsWith('.sql'))
    .sort(); // alphabetical order
}

const files = getSqlFiles(MIGRATIONS_DIR);

if (files.length === 0) {
  console.log('No migration SQL files found.');
} else {
  console.log('Found migration files:');
  files.forEach(f => console.log(`- ${f}`));
}

// Export for possible future use
module.exports = { getSqlFiles };
