#!/usr/bin/env node

/**
 * migrate.js
 *
 * Simple migration script that scans a `./migrations/` directory for
 * `.sql` files and logs the filenames it would apply.
 * The files are processed in natural order (sorted alphabetically),
 * which is a common convention for SQL migration scripts.
 *
 * ## Usage
 * ```bash
 * node migrate.js
 * ```
 *
 * This script is deliberately lightweight – it does *not* attempt to
 * execute the SQL or keep track of which migrations have already been run.
 * It merely demonstrates how one might enumerate migration files.
 */

const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function main() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migration directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const allFiles = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for files ending with .sql (case‑insensitive)
  const sqlFiles = allFiles.filter((file) => {
    const ext = path.extname(file).toLowerCase();
    return ext === '.sql';
  });

  // Sort alphabetically – many projects order migrations by filename
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration(s).`);
  sqlFiles.forEach((file, idx) => {
    console.log(`${idx + 1}. ${file}`);
  });
}

main();

