const fs = require('fs');
const path = require('path');

/**
 * Load key/value pairs from a .env.* file into process.env.
 * This implementation is intentionally lightweight and avoids pulling
 * in a full‐blown dotenv package – perfect for a small script.
 */
function loadEnvFromFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`Environment file not found: ${filePath}`);
    return;
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split(/\r?\n/);

  lines.forEach((line) => {
    // Skip comments and empty lines
