// migrate.js
// This script reads all SQL files from the ./migrations/ directory
// and logs each filename in the order they would be applied.
// It does NOT actually execute the SQL statements.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

function getMigratedFiles() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.warn(`Migrations directory ${MIGRATIONS_DIR} does not exist.`);
    return [];
  }
  // Read all files, filter .sql files
  const files = fs.readdirSync(MIGRATIONS_DIR)
    .filter((f) => f.endsWith('.sql'))
    .sort(); // natural order based on filename
  return files;
}

function logMigrationSequence() {
  const files = getMigratedFiles();
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migration sequence:');
  files.forEach((file) => {
    console.log(`- ${file}`);
  });
}

// If run directly, log the sequence
if (require.main === module) {
  logMigrationSequence();
}

module.exports = {
  getMigratedFiles,
  logMigrationSequence,
};

