```js
// migrate.js
// Reads all SQL migration files from ./migrations/ and logs their filenames
// in the order they would be applied. Does NOT execute the SQL.

const fs   = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

/**
 * Get the list of migration files in the migrations directory.
 * @returns {string[]} An array of filenames (sorted alphabetically).
 */
function getMigratedFiles() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.warn(`Migrations directory ${MIGRATIONS_DIR} does not exist.`);
    return [];
  }

  // Read the directory, filter only `.sql` files, and sort.
  const files = fs
    .readdirSync(MIGRATIONS_DIR)
    .filter((f) => f.endsWith('.sql'))
    .sort(); // Natural order based on filename

  return files;
}

/**
 * Log the migration sequence to the console.
 */
function logMigrationSequence() {
  const files = getMigratedFiles();

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migration sequence:');
  files.forEach((file) => {
    console.log(`- ${file}`);
  });
}

// If the script is run directly (`node migrate.js`), run the logging function.
if (require.main === module) {
  logMigrationSequence();
}

module.exports = { getMigratedFiles, logMigrationSequence };
```

### Usage

```bash
node migrate.js
```

It will print something like:

```
Migration sequence:
- 001_create_users_table.sql
- 002_add_indexes.sql
...
```

If you don’t have any migration files, you’ll see:

```
No migration files found.
```

Feel free to extend the script later to actually execute the SQL, keep track of applied migrations, etc. This version simply provides the requested logging functionality.
